    20	sub validate_absolute_path {
    21	    my ($label, $value) = @_;
    22	    my $shown_value = defined($value) && $value ne '' ? $value : 'unset';
    23	
    24	    defined($value) && $value =~ m{\A/} ||
    25	        fatal("$label must be an absolute path: $shown_value");
    26	    $value ne '/' &&
    27	        index($value, '..') == -1 &&
    28	        index($value, '//') == -1 &&
    29	        $value !~ /[^A-Za-z0-9._\/\@%:+,\-]/ ||
    30	        fatal("$label contains unsupported path syntax: $value");
    31	}
    32	
    33	sub validate_real_directory {
    34	    my ($label, $path) = @_;
    35	
    36	    -d $path && !-l $path ||
    37	        fatal("$label must be a real directory: $path");
    38	}
    39	
    40	sub validate_root_owned_file {
    41	    my ($label, $path, $max_bytes) = @_;
    42	
    43	    -f $path && !-l $path ||
    44	        fatal("$label must be a regular non-symlink file: $path");
    45	    my ($owner_uid, $permissions, $size_bytes, $file_type) =
    46	        _file_metadata($path);
    47	    $file_type == 0100000 ||
    48	        fatal("$label must be a regular non-symlink file: $path");
    49	    $owner_uid == 0 ||
    50	        fatal("$label must be owned by root: $path");
    51	    !($permissions & 0022) ||
    52	        fatal("$label must not be group- or world-writable: $path");
    53	    $size_bytes <= $max_bytes ||
    54	        fatal("$label exceeds ${max_bytes} bytes: $path");
    55	}
    56	
    57	sub read_bounded_file {
    58	    my ($label, $path, $max_bytes) = @_;
    59	
    60	    -l $path && fatal("$label must not be a symlink: $path");
    61	    sysopen my $fh, $path, O_RDONLY | O_NOFOLLOW ||
    62	        fatal("cannot read $label: $path");
    63	    binmode $fh, ':raw' ||
    64	        fatal("cannot read $label: $path");
    65	
    66	    my $content = '';
    67	    my $remaining = $max_bytes + 1;
    68	    while ($remaining > 0) {
    69	        my $buffer = '';
    70	        my $read = sysread(
    71	            $fh,
    72	            $buffer,
    73	            $remaining > 65_536 ? 65_536 : $remaining,
    74	        );
    75	        defined($read) || fatal("cannot read $label: $path");
    76	        last if $read == 0;
    77	        $content .= $buffer;
    78	        $remaining -= $read;
    79	    }
    80	    close $fh || fatal("cannot read $label: $path");
    81	
    82	    length($content) <= $max_bytes ||
    83	        fatal("$label exceeds ${max_bytes} bytes: $path");
    84	    return $content;
    85	}
