   509	            or fatal("cannot prune managed artifact $filename: $!");
   510	    }
   511	}
   512	
   513	sub transcribe_recording {
   514	    my ($runtime, $home, $state) = @_;
   515	    my $config = whisper_config();
   516	    my $paths = resolved_recording_paths($home);
   517	    my $sleek = resolved_sleek_paths($home);
   518	    my $expected_wav = safe_child_path($paths->{audio}, "$state->{stem}.wav");
   519	    $state->{wav} eq $expected_wav
   520	        or fatal('runtime state recording path is outside the managed audio directory');
   521	    -f $state->{wav} && !-l $state->{wav} && -s $state->{wav} > 44
   522	        or fatal('recorded WAV is missing or too small to transcribe');
   523	
   524	    my $output_prefix = safe_child_path(
   525	        $runtime,
   526	        '.whisper-' . $state->{stem} . "-$$",
   527	    );
   528	    my $output_json = "$output_prefix.json";
   529	    unlink $output_json if -e $output_json && !-l $output_json;
   530	
   531	    my $threads = runtime_thread_count($config->{WHISPER_RUNTIME_THREADS});
   532	    my @command = (
   533	        $config->{WHISPER_CLI},
   534	        '--model', $config->{WHISPER_MODEL},
   535	        '--file', $state->{wav},
   536	        '--threads', "$threads",
   537	        '--output-json',
   538	        '--no-timestamps',
   539	        '--output-file', $output_prefix,
   540	    );
   541	    my $status = system { $command[0] } @command;
   542	    if ($status != 0) {
   543	        my $code = $status == -1 ? "exec error: $!" : "exit status " . ($status >> 8);
   544	        fatal("whisper-cli transcription failed: $code");
   545	    }
   546	    -f $output_json && !-l $output_json
   547	        or fatal('whisper-cli did not produce JSON output');
   548	
   549	    my $parsed = read_json_object($output_json, 8 * 1024 * 1024, 'whisper-cli output');
   550	    unlink $output_json or fatal("cannot remove transient whisper-cli JSON: $!");
   551	    my $text = transcript_from_whisper_json($parsed);
   552	
   553	    atomic_write_bytes(
   554	        $paths->{transcribed},
   555	        "$state->{stem}.json",
   556	        encode_json({ text => $text }) . "\n",
   557	        0600,
   558	    );
   559	    append_todo_entry($sleek, $state->{stem}, $text);
   560	    prune_timestamped_files($paths->{audio}, 'wav');
   561	    prune_timestamped_files($paths->{transcribed}, 'json');
   562	}
   563	
   564	sub stop_recording {
   565	    my ($runtime, $home) = @_;
   566	    my $state = read_state($runtime);
   567	    return unless $state;
   568	    if (process_matches_state($state)) {
   569	        kill 'TERM', $state->{pid}
   570	            or fatal("cannot stop pw-record: $!");
   571	        wait_for_recording_exit($state)
   572	            or fatal('pw-record did not stop within 15 seconds');
   573	    }
   574	    clear_state($runtime);
   575	    set_default_audio_source_muted(1);
   576	    transcribe_recording($runtime, $home, $state);
   577	}
   578	
   579	sub main {
   580	    @ARGV <= 1 or fatal('usage: whisper-record-toggle [start|stop|toggle]');
   581	    my $action = $ARGV[0] // 'toggle';
   582	    $action =~ /\A(?:start|stop|toggle)\z/
   583	        or fatal('usage: whisper-record-toggle [start|stop|toggle]');
   584	
   585	    my $runtime = runtime_directory();
   586	    my $home = home_directory();
   587	    my $lock = open_runtime_lock($runtime, LOCK_EX);
   588	    my $state = read_state($runtime);
   589	    if ($action eq 'toggle') {
   590	        if ($state && process_matches_state($state)) {
   591	            stop_recording($runtime, $home);
   592	        } else {
   593	            clear_state($runtime) if $state;
   594	            start_recording($runtime, $home);
   595	        }
   596	    } elsif ($action eq 'start') {
   597	        start_recording($runtime, $home);
   598	    } else {
   599	        stop_recording($runtime, $home);
   600	    }
   601	}
   602	
   603	main();
