    my $size = -s $path;
    defined $size && $size <= $limit
        or fatal("file is too large to parse safely: $path");
    open my $fh, '<:raw', $path
        or fatal("cannot read $path: $!");
    local $/;
    my $content = <$fh>;
    close $fh or fatal("cannot close $path: $!");
    return defined $content ? $content : q{};
}

sub read_json_object {
    my ($path, $limit, $label) = @_;
    my $raw = read_raw_limited($path, $limit);
    my $data = eval { decode_json($raw) };
    $@ and fatal("$label is not valid JSON");
    ref $data eq 'HASH' or fatal("$label must contain a JSON object");
    return $data;
}

sub atomic_write_bytes {
    my ($directory, $filename, $bytes, $mode) = @_;
    my ($fh, $temp_path) = tempfile(
        ".${filename}.tmp.XXXXXX",
        DIR    => $directory,
        UNLINK => 0,
    );
    binmode $fh, ':raw'
        or fatal("cannot configure temporary file encoding: $!");
    print {$fh} $bytes
        or fatal("cannot write temporary file: $!");
    close $fh or fatal("cannot close temporary file: $!");
    chmod $mode, $temp_path
        or fatal("cannot set temporary file mode: $!");
    my $destination = safe_child_path($directory, $filename);
    rename $temp_path, $destination
        or fatal("cannot atomically publish $destination: $!");
    return $destination;
}

sub write_state {
    my ($runtime, $state) = @_;
    atomic_write_bytes(
        $runtime,
        $STATE_NAME,
        encode_json($state) . "\n",
        0600,
    );
}

sub clear_state {
    my ($runtime) = @_;
    my $path = state_path($runtime);
    return unless -e $path;
    !-l $path && -f $path
        or fatal("runtime state is not a regular file: $path");
    my @stat = lstat_or_fatal('runtime state', $path);
    $stat[4] == $< or fatal("runtime state must be owned by the active user: $path");
    unlink $path or fatal("cannot clear runtime state: $!");
}

sub read_state {
    my ($runtime) = @_;
    my $path = state_path($runtime);
    return undef unless -e $path;
    !-l $path && -f $path
        or fatal("runtime state is not a regular file: $path");
    my @stat = lstat_or_fatal('runtime state', $path);
    $stat[4] == $< or fatal("runtime state must be owned by the active user: $path");
    my $state = read_json_object($path, 32 * 1024, 'runtime state');
    for my $key (qw(pid stem wav)) {
        exists $state->{$key} && defined $state->{$key}
            or fatal("runtime state is missing $key");
    }
    $state->{pid} =~ /\A[1-9][0-9]*\z/
        or fatal('runtime state contains an invalid process ID');
    $state->{stem} =~ /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\z/
        or fatal('runtime state contains an invalid timestamp stem');
    is_safe_absolute_path($state->{wav})
        or fatal('runtime state contains an invalid recording path');
    return $state;
}

sub resolved_recording_paths {
    my ($home) = @_;
    my $music = File::Spec->catdir($home, 'Music');
    my $whisper = File::Spec->catdir($music, 'Whisper');
    my $audio = File::Spec->catdir($whisper, 'audio');
    my $transcribed = File::Spec->catdir($whisper, 'transcribed');
    assert_user_owned_directory('Whisper audio directory', $audio, 0700);
    assert_user_owned_directory('Whisper transcription directory', $transcribed, 0700);
    return {
        audio       => $audio,
        transcribed => $transcribed,
    };
}

sub resolved_sleek_paths {
    my ($home) = @_;
    my $task_dir = File::Spec->catdir($home, 'Syncthing', 'sleek');
    assert_user_owned_directory('Sleek task directory', $task_dir, 0700);
    my $task_file = safe_child_path($task_dir, 'whisper.txt');
    if (-e $task_file) {
        !-l $task_file && -f $task_file
            or fatal("Sleek task file is not regular: $task_file");
        my @stat = lstat_or_fatal('Sleek task file', $task_file);
        $stat[4] == $< or fatal("Sleek task file must be owned by the active user");
    } else {
        atomic_write_bytes($task_dir, 'whisper.txt', q{}, 0600);
    }
    chmod 0600, $task_file
        or fatal("cannot set Sleek task file mode: $!");
    return {
        directory => $task_dir,
== toggle config and recording lifecycle ==
        directory => $task_dir,
        task_file => $task_file,
    };
}

sub config_file_path {
    my $path = $ENV{WHISPER_CONFIG_FILE} // $DEFAULT_CONFIG;
    assert_safe_absolute_path('Whisper configuration', $path);
    -f $path && !-l $path
        or fatal("Whisper configuration is unavailable: $path");
    my @stat = lstat_or_fatal('Whisper configuration', $path);
    ($stat[2] & 0022) == 0
        or fatal('Whisper configuration must not be writable by other users');
    if ($path eq $DEFAULT_CONFIG) {
        $stat[4] == 0
            or fatal('default Whisper configuration must be owned by root');
    } else {
        $stat[4] == $<
            or fatal('override Whisper configuration must be owned by the active user');
    }
    return $path;
}

sub whisper_config {
    my $path = config_file_path();
    my $raw = read_raw_limited($path, 16 * 1024);
    my %config;
    for my $line (split /\n/, $raw) {
        next if $line eq q{} || $line =~ /\A#/;
        $line =~ /\A([A-Z_]+)=([^\r\n]*)\z/
            or fatal("Whisper configuration contains an invalid line");
        my ($key, $value) = ($1, $2);
        exists $config{$key}
            and fatal("Whisper configuration contains duplicate $key");
        $config{$key} = $value;
    }
    for my $key (qw(WHISPER_CLI WHISPER_MODEL WHISPER_RUNTIME_THREADS)) {
        exists $config{$key} && length $config{$key}
            or fatal("Whisper configuration is missing $key");
    }
    assert_safe_absolute_path('WHISPER_CLI', $config{WHISPER_CLI});
    assert_safe_absolute_path('WHISPER_MODEL', $config{WHISPER_MODEL});
    -x $config{WHISPER_CLI} && -f $config{WHISPER_CLI}
        or fatal("Whisper CLI is unavailable: $config{WHISPER_CLI}");
    -r $config{WHISPER_MODEL} && -f $config{WHISPER_MODEL}
        or fatal("Whisper model is unavailable: $config{WHISPER_MODEL}");
    $config{WHISPER_RUNTIME_THREADS} =~ /\A(?:auto|[1-9][0-9]*)\z/
        or fatal('WHISPER_RUNTIME_THREADS must be auto or a positive integer');
    return \%config;
}

sub runtime_thread_count {
    my ($configured) = @_;
    return $configured if $configured ne 'auto';
    my $count = eval {
        my $value = POSIX::sysconf(POSIX::_SC_NPROCESSORS_ONLN());
        return $value if defined $value && $value > 0;
        return undef;
    };
    return $count if defined $count && $count =~ /\A[1-9][0-9]*\z/;
    return 1;
}

sub pw_record_binary {
    my $path = $ENV{WHISPER_PW_RECORD_BIN} // '/usr/bin/pw-record';
    assert_safe_absolute_path('pw-record path', $path);
    -x $path && -f $path
        or fatal("pw-record is unavailable: $path");
    return $path;
}

sub set_default_audio_source_muted {
    my ($muted) = @_;
    $muted == 0 || $muted == 1
        or fatal('default audio source mute state must be 0 or 1');

    my $wpctl = '/usr/bin/wpctl';
    -x $wpctl && -f $wpctl
        or fatal("wpctl is unavailable: $wpctl");
    my $status = system {
        $wpctl
    } $wpctl, 'set-mute', '@DEFAULT_AUDIO_SOURCE@', "$muted";
    return if $status == 0;

    my $detail = $status == -1
        ? "exec error: $!"
        : 'exit status ' . ($status >> 8);
    fatal("cannot set default audio source mute state: $detail");
}

sub timestamp_stem {
    my ($audio_directory) = @_;
    for (1 .. 3) {
        my $stem = strftime('%Y-%m-%d-%H-%M-%S', localtime);
        my $candidate = safe_child_path($audio_directory, "$stem.wav");
        return $stem unless -e $candidate;
        sleep 1.0;
    }
    fatal('could not create a collision-free timestamped recording name');
}

sub start_recording {
    my ($runtime, $home) = @_;
    my $paths = resolved_recording_paths($home);
    my $state = read_state($runtime);
    if ($state && recording_is_active($runtime)) {
        set_default_audio_source_muted(0);
        return;
    }
    clear_state($runtime) if $state;
    my $recording_guard = open_recording_guard($runtime, LOCK_EX | LOCK_NB);
    defined $recording_guard or fatal('a Whisper recording is already active');

    my $stem = timestamp_stem($paths->{audio});
    my $wav = safe_child_path($paths->{audio}, "$stem.wav");
    my $pw_record = pw_record_binary();
    my $log_path = safe_child_path($runtime, 'whisper-record-toggle.log');

    # Keep the microphone muted when idle.  Unmute it before opening the
    # capture stream so Waybar's native {format_source} becomes active as
    # soon as this toggle begins recording.
    set_default_audio_source_muted(0);
    my $pid = fork();
    if (!defined $pid) {
        set_default_audio_source_muted(1);
        fatal("cannot start pw-record: $!");
    }
    if ($pid == 0) {
        open STDIN, '<', '/dev/null' or exit 127;
        open STDOUT, '>', '/dev/null' or exit 127;
        open STDERR, '>>', $log_path or exit 127;
        chmod 0600, $log_path;
        exec {
            $pw_record
        } $pw_record, '--rate=16000', '--channels=1', '--format=s16', $wav;
        exit 127;
    }

    sleep 0.1;
    if (!kill(0, $pid)) {
        kill 'TERM', $pid;
        waitpid $pid, 0;
        close $recording_guard
            or fatal("cannot close recording guard: $!");
        set_default_audio_source_muted(1);
        fatal('pw-record did not remain active after startup');
    }

    my $recording_state = {
        pid  => "$pid",
        stem => $stem,
        wav  => $wav,
    };
    my $state_written = eval {
        write_state($runtime, $recording_state);
        1;
    };
    if ($state_written) {
        close $recording_guard
            or fatal("cannot close recording guard: $!");
        return;
    }

    my $error = $@ || 'cannot publish Whisper recording state';
    kill 'TERM', $pid if kill(0, $pid);
    close $recording_guard
        or fatal("cannot close recording guard: $!");
    wait_for_recording_exit($runtime);
    eval {
        set_default_audio_source_muted(1);
        1;
    };
    die $error;
}

sub wait_for_recording_exit {
    my ($runtime) = @_;
    for (1 .. 150) {
        return 1 unless recording_is_active($runtime);
        sleep 0.1;
    }
    return 0;
}

sub normalize_transcript {
    my ($text) = @_;
    $text = q{} unless defined $text;
    $text =~ s/[\p{Cc}\p{Cf}]+/ /gu;
    $text =~ s/\s+/ /gu;
    $text =~ s/\A\s+//u;
    $text =~ s/\s+\z//u;
== toggle transcription and main ==
    $text =~ s/\s+\z//u;
    return $text;
}

sub transcript_from_whisper_json {
    my ($data) = @_;
    my @parts;
    if (ref $data->{transcription} eq 'ARRAY') {
        for my $segment (@{ $data->{transcription} }) {
            next unless ref $segment eq 'HASH' && defined $segment->{text};
            push @parts, $segment->{text};
        }
    } elsif (ref $data->{segments} eq 'ARRAY') {
        for my $segment (@{ $data->{segments} }) {
            next unless ref $segment eq 'HASH' && defined $segment->{text};
            push @parts, $segment->{text};
        }
    } elsif (defined $data->{text}) {
        push @parts, $data->{text};
    } elsif (ref $data->{result} eq 'HASH' && defined $data->{result}{text}) {
        push @parts, $data->{result}{text};
    }
    return normalize_transcript(join q{ }, @parts);
}

sub append_todo_entry {
    my ($sleek, $stem, $text) = @_;
    return unless length $text;
    my $lock_path = safe_child_path($sleek->{directory}, '.whisper.txt.lock');
    sysopen my $lock, $lock_path, O_CREAT | O_RDWR, 0600
        or fatal("cannot open Sleek task lock: $!");
    flock($lock, LOCK_EX)
        or fatal("cannot lock Sleek task file: $!");
    open my $fh, '>>:encoding(UTF-8)', $sleek->{task_file}
        or fatal("cannot append to Sleek task file: $!");
    my $date = substr($stem, 0, 10);
    print {$fh} "$date $text +whisper \@voice source:$stem\n"
        or fatal("cannot write Sleek task entry: $!");
    close $fh or fatal("cannot close Sleek task file: $!");
}

sub prune_timestamped_files {
    my ($directory, $extension) = @_;
    opendir my $dh, $directory
        or fatal("cannot read managed directory: $!");
    my @files = grep {
        /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\.\Q$extension\E\z/
            && -f File::Spec->catfile($directory, $_)
            && !-l File::Spec->catfile($directory, $_)
    } readdir $dh;
    closedir $dh or fatal("cannot close managed directory: $!");
    @files = sort { $b cmp $a } @files;
    for my $filename (@files[$MAX_ARTIFACTS .. $#files]) {
        unlink safe_child_path($directory, $filename)
            or fatal("cannot prune managed artifact $filename: $!");
    }
}

sub transcribe_recording {
    my ($runtime, $home, $state) = @_;
    my $config = whisper_config();
    my $paths = resolved_recording_paths($home);
    my $sleek = resolved_sleek_paths($home);
    my $expected_wav = safe_child_path($paths->{audio}, "$state->{stem}.wav");
    $state->{wav} eq $expected_wav
        or fatal('runtime state recording path is outside the managed audio directory');
    -f $state->{wav} && !-l $state->{wav} && -s $state->{wav} > 44
        or fatal('recorded WAV is missing or too small to transcribe');

    my $output_prefix = safe_child_path(
        $runtime,
        '.whisper-' . $state->{stem} . "-$$",
    );
    my $output_json = "$output_prefix.json";
    unlink $output_json if -e $output_json && !-l $output_json;

    my $threads = runtime_thread_count($config->{WHISPER_RUNTIME_THREADS});
    my @command = (
        $config->{WHISPER_CLI},
        '--model', $config->{WHISPER_MODEL},
        '--file', $state->{wav},
        '--threads', "$threads",
        '--output-json',
        '--no-timestamps',
        '--output-file', $output_prefix,
    );
    my $status = system { $command[0] } @command;
    if ($status != 0) {
        my $code = $status == -1 ? "exec error: $!" : "exit status " . ($status >> 8);
        fatal("whisper-cli transcription failed: $code");
    }
    -f $output_json && !-l $output_json
        or fatal('whisper-cli did not produce JSON output');

    my $parsed = read_json_object($output_json, 8 * 1024 * 1024, 'whisper-cli output');
    unlink $output_json or fatal("cannot remove transient whisper-cli JSON: $!");
    my $text = transcript_from_whisper_json($parsed);

    atomic_write_bytes(
        $paths->{transcribed},
        "$state->{stem}.json",
        encode_json({ text => $text }) . "\n",
        0600,
    );
    append_todo_entry($sleek, $state->{stem}, $text);
    prune_timestamped_files($paths->{audio}, 'wav');
    prune_timestamped_files($paths->{transcribed}, 'json');
}

sub stop_recording {
    my ($runtime, $home) = @_;
    my $state = read_state($runtime);
    return unless $state;
    if (recording_is_active($runtime)) {
        kill 'TERM', $state->{pid}
            or fatal("cannot stop pw-record: $!");
        wait_for_recording_exit($runtime)
            or fatal('pw-record did not stop within 15 seconds');
    }
    clear_state($runtime);
    set_default_audio_source_muted(1);
    transcribe_recording($runtime, $home, $state);
}

sub main {
    @ARGV <= 1 or fatal('usage: whisper-record-toggle [start|stop|toggle]');
    my $action = $ARGV[0] // 'toggle';
    $action =~ /\A(?:start|stop|toggle)\z/
        or fatal('usage: whisper-record-toggle [start|stop|toggle]');

    my $runtime = runtime_directory();
    my $home = home_directory();
    my $lock = open_runtime_lock($runtime, LOCK_EX);
    my $state = read_state($runtime);
    if ($action eq 'toggle') {
        if ($state && recording_is_active($runtime)) {
            stop_recording($runtime, $home);
        } else {
            clear_state($runtime) if $state;
            start_recording($runtime, $home);
        }
    } elsif ($action eq 'start') {
        start_recording($runtime, $home);
    } else {
        stop_recording($runtime, $home);
    }
}

