   407	    my ($paths, $state) = @_;
   408	    my $expected_wav = safe_child_path($paths->{audio}, "$state->{stem}.wav");
   409	    $state->{wav} eq $expected_wav
   410	        or fatal('runtime state recording path is outside the managed audio directory');
   411	    return $expected_wav;
   412	}
   413	
   414	sub state_wav_has_audio {
   415	    my ($paths, $state) = @_;
   416	    my $wav = assert_state_wav_path($paths, $state);
   417	    return -f $wav && !-l $wav && -s $wav > 44;
   418	}
   419	
   420	sub start_recording {
   421	    my ($runtime, $home) = @_;
   422	    my $paths = resolved_recording_paths($home);
   423	    my $state = read_state($runtime);
   424	    if (record_service_is_active()) {
   425	        $state or fatal('the Whisper recorder is active without managed runtime state');
   426	        assert_state_wav_path($paths, $state);
   427	        set_default_audio_source_muted(0);
   428	        return;
   429	    }
   430	    if ($state) {
   431	        if (state_wav_has_audio($paths, $state)) {
   432	            fatal('a completed Whisper recording is pending transcription; retry stop before starting another recording');
   433	        }
   434	        clear_state($runtime);
   435	    }
   436	
   437	    my $stem = timestamp_stem($paths->{audio});
   438	    my $wav = safe_child_path($paths->{audio}, "$stem.wav");
   439	    write_state(
   440	        $runtime,
   441	        {
   442	            stem => $stem,
   443	            wav  => $wav,
   444	        },
   445	    );
   446	
   447	    # Keep the microphone muted when idle. Unmute it before requesting the
   448	    # user manager to open the capture stream so Waybar's native
   449	    # {format_source} becomes active when the recorder starts.
   450	    set_default_audio_source_muted(0);
   451	    user_systemctl('reset-failed', $RECORD_SERVICE);
   452	    my $status = user_systemctl('start', $RECORD_SERVICE);
   453	    if ($status == 0 && wait_for_record_service_active()) {
   454	        return;
   455	    }
   456	
   457	    my $detail = systemctl_status_detail($status);
   458	    user_systemctl('stop', $RECORD_SERVICE) if record_service_is_active();
   459	    clear_state($runtime);
   460	    set_default_audio_source_muted(1);
   461	    fatal("cannot start $RECORD_SERVICE: $detail");
   462	}
   463	
   464	sub record_worker {
   465	    my ($runtime, $home) = @_;
   466	    my $state = read_state($runtime)
   467	        or fatal('the recorder service was started without managed runtime state');
   468	    my $paths = resolved_recording_paths($home);
   469	    my $wav = assert_state_wav_path($paths, $state);
   470	    my $recording_guard = open_recording_guard($runtime, LOCK_EX | LOCK_NB);
   471	    defined $recording_guard
   472	        or fatal('a Whisper recording is already active');
   473	    my $pw_record = pw_record_binary();
   474	
   475	    exec {
   476	        $pw_record
   477	    } $pw_record, '--rate=16000', '--channels=1', '--format=s16', $wav
   478	        or fatal("cannot exec pw-record: $!");
   479	}
   480	
   481	sub normalize_transcript {
   482	    my ($text) = @_;
   483	    $text = q{} unless defined $text;
   484	    $text =~ s/[\p{Cc}\p{Cf}]+/ /gu;
   485	    $text =~ s/\s+/ /gu;
   486	    $text =~ s/\A\s+//u;
   487	    $text =~ s/\s+\z//u;
   488	    return $text;
   489	}
   490	
   491	sub transcript_from_whisper_json {
   492	    my ($data) = @_;
   493	    my @parts;
   494	    if (ref $data->{transcription} eq 'ARRAY') {
   495	        for my $segment (@{ $data->{transcription} }) {
   496	            next unless ref $segment eq 'HASH' && defined $segment->{text};
   497	            push @parts, $segment->{text};
   498	        }
   499	    } elsif (ref $data->{segments} eq 'ARRAY') {
   500	        for my $segment (@{ $data->{segments} }) {
   501	            next unless ref $segment eq 'HASH' && defined $segment->{text};
   502	            push @parts, $segment->{text};
   503	        }
   504	    } elsif (defined $data->{text}) {
   505	        push @parts, $data->{text};
   506	    } elsif (ref $data->{result} eq 'HASH' && defined $data->{result}{text}) {
   507	        push @parts, $data->{result}{text};
   508	    }
   509	    return normalize_transcript(join q{ }, @parts);
   510	}
   511	
   512	sub append_todo_entry {
   513	    my ($sleek, $stem, $text) = @_;
   514	    return unless length $text;
   515	    my $lock_path = safe_child_path($sleek->{directory}, '.whisper.txt.lock');
   516	    sysopen my $lock, $lock_path, O_CREAT | O_RDWR, 0600
   517	        or fatal("cannot open Sleek task lock: $!");
   518	    flock($lock, LOCK_EX)
   519	        or fatal("cannot lock Sleek task file: $!");
   520	    open my $fh, '>>:encoding(UTF-8)', $sleek->{task_file}
   521	        or fatal("cannot append to Sleek task file: $!");
   522	    my $date = substr($stem, 0, 10);
   523	    print {$fh} "$date $text +whisper \@voice source:$stem\n"
   524	        or fatal("cannot write Sleek task entry: $!");
   525	    close $fh or fatal("cannot close Sleek task file: $!");
   526	}
   527	
   528	sub prune_timestamped_files {
   529	    my ($directory, $extension) = @_;
   530	    opendir my $dh, $directory
   531	        or fatal("cannot read managed directory: $!");
   532	    my @files = grep {
   533	        /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\.\Q$extension\E\z/
   534	            && -f File::Spec->catfile($directory, $_)
   535	            && !-l File::Spec->catfile($directory, $_)
   536	    } readdir $dh;
   537	    closedir $dh or fatal("cannot close managed directory: $!");
   538	    @files = sort { $b cmp $a } @files;
   539	    for my $filename (@files[$MAX_ARTIFACTS .. $#files]) {
   540	        unlink safe_child_path($directory, $filename)
   541	            or fatal("cannot prune managed artifact $filename: $!");
   542	    }
   543	}
   544	
   545	sub transcribe_recording {
   546	    my ($runtime, $home, $state) = @_;
   547	    my $config = whisper_config();
   548	    my $paths = resolved_recording_paths($home);
   549	    my $sleek = resolved_sleek_paths($home);
   550	    my $expected_wav = assert_state_wav_path($paths, $state);
   551	    -f $expected_wav && !-l $expected_wav && -s $expected_wav > 44
   552	        or fatal('recorded WAV is missing or too small to transcribe');
   553	
   554	    my $output_prefix = safe_child_path(
   555	        $runtime,
   556	        '.whisper-' . $state->{stem} . "-$$",
   557	    );
   558	    my $output_json = "$output_prefix.json";
   559	    unlink $output_json if -e $output_json && !-l $output_json;
   560	
   561	    my $threads = runtime_thread_count($config->{WHISPER_RUNTIME_THREADS});
   562	    my @command = (
   563	        $config->{WHISPER_CLI},
   564	        '--model', $config->{WHISPER_MODEL},
   565	        '--file', $state->{wav},
   566	        '--threads', "$threads",
   567	        '--output-json',
   568	        '--no-timestamps',
   569	        '--output-file', $output_prefix,
   570	    );
   571	    my $status = system { $command[0] } @command;
   572	    if ($status != 0) {
   573	        my $code = $status == -1 ? "exec error: $!" : "exit status " . ($status >> 8);
   574	        fatal("whisper-cli transcription failed: $code");
   575	    }
   576	    -f $output_json && !-l $output_json
   577	        or fatal('whisper-cli did not produce JSON output');
   578	
   579	    my $parsed = read_json_object($output_json, 8 * 1024 * 1024, 'whisper-cli output');
   580	    unlink $output_json or fatal("cannot remove transient whisper-cli JSON: $!");
   581	    my $text = transcript_from_whisper_json($parsed);
   582	
   583	    atomic_write_bytes(
   584	        $paths->{transcribed},
   585	        "$state->{stem}.json",
   586	        encode_json({ text => $text }) . "\n",
   587	        0600,
   588	    );
   589	    append_todo_entry($sleek, $state->{stem}, $text);
   590	    prune_timestamped_files($paths->{audio}, 'wav');
   591	    prune_timestamped_files($paths->{transcribed}, 'json');
   592	}
   593	
   594	sub stop_recording {
   595	    my ($runtime, $home) = @_;
   596	    my $state = read_state($runtime);
   597	    if (record_service_is_active()) {
   598	        my $status = user_systemctl('stop', $RECORD_SERVICE);
   599	        $status == 0
   600	            or fatal("cannot stop $RECORD_SERVICE: " . systemctl_status_detail($status));
   601	        wait_for_record_service_inactive()
   602	            or fatal("$RECORD_SERVICE did not stop within 15 seconds");
   603	    }
   604	    set_default_audio_source_muted(1);
   605	    return undef unless $state;
   606	
   607	    my $paths = resolved_recording_paths($home);
   608	    if (!state_wav_has_audio($paths, $state)) {
   609	        clear_state($runtime);
   610	        return undef;
   611	    }
   612	    return $state;
   613	}
   614	
   615	sub transcribe_pending_recording {
   616	    my ($runtime, $home) = @_;
   617	    my $state = read_state($runtime);
   618	    return unless $state;
   619	    record_service_is_active()
   620	        and fatal('cannot transcribe while the Whisper recorder is active');
   621	    transcribe_recording($runtime, $home, $state);
   622	    clear_state($runtime);
   623	}
   624	
   625	sub start_transcribe_service {
   626	    my $status = user_systemctl('start', $TRANSCRIBE_SERVICE);
   627	    $status == 0
   628	        or fatal("cannot start $TRANSCRIBE_SERVICE: " . systemctl_status_detail($status));
   629	}
   630	
   631	sub main {
   632	    @ARGV <= 1 or fatal('usage: whisper-record-toggle [start|stop|toggle]');
   633	    my $action = $ARGV[0] // 'toggle';
   634	    $action =~ /\A(?:start|stop|toggle|record-worker|transcribe)\z/
   635	        or fatal('usage: whisper-record-toggle [start|stop|toggle]');
   636	
   637	    my $runtime = runtime_directory();
   638	    my $home = home_directory();
   639	    if ($action eq 'record-worker') {
   640	        my $lock = open_runtime_lock($runtime, LOCK_EX);
   641	        record_worker($runtime, $home);
   642	        return;
   643	    }
   644	    if ($action eq 'transcribe') {
   645	        my $lock = open_runtime_lock($runtime, LOCK_EX);
   646	        transcribe_pending_recording($runtime, $home);
   647	        return;
   648	    }
   649	
   650	    my $transcribe = 0;
   651	    my $lock = open_runtime_lock($runtime, LOCK_EX);
   652	    my $state = read_state($runtime);
   653	    if ($action eq 'toggle') {
   654	        if (record_service_is_active() || $state) {
   655	            $transcribe = defined stop_recording($runtime, $home);
   656	        } else {
   657	            start_recording($runtime, $home);
   658	        }
   659	    } elsif ($action eq 'start') {
   660	        start_recording($runtime, $home);
   661	    } else {
   662	        $transcribe = defined stop_recording($runtime, $home);
   663	    }
   664	    undef $lock;
   665	    start_transcribe_service() if $transcribe;
   666	}
   667	
   668	main();

