   267	sub config_file_path {
   268	    my $path = $ENV{WHISPER_CONFIG_FILE} // $DEFAULT_CONFIG;
   269	    assert_safe_absolute_path('Whisper configuration', $path);
   270	    -f $path && !-l $path
   271	        or fatal("Whisper configuration is unavailable: $path");
   272	    my @stat = lstat_or_fatal('Whisper configuration', $path);
   273	    ($stat[2] & 0022) == 0
   274	        or fatal('Whisper configuration must not be writable by other users');
   275	    if ($path eq $DEFAULT_CONFIG) {
   276	        $stat[4] == 0
   277	            or fatal('default Whisper configuration must be owned by root');
   278	    } else {
   279	        $stat[4] == $<
   280	            or fatal('override Whisper configuration must be owned by the active user');
   281	    }
   282	    return $path;
