   285	sub whisper_config {
   286	    my $path = config_file_path();
   287	    my $raw = read_raw_limited($path, 16 * 1024);
   288	    my %config;
   289	    for my $line (split /\n/, $raw) {
   290	        next if $line eq q{} || $line =~ /\A#/;
   291	        $line =~ /\A([A-Z_]+)=([^\r\n]*)\z/
   292	            or fatal("Whisper configuration contains an invalid line");
   293	        my ($key, $value) = ($1, $2);
   294	        exists $config{$key}
   295	            and fatal("Whisper configuration contains duplicate $key");
   296	        $config{$key} = $value;
   297	    }
   298	    for my $key (qw(WHISPER_CLI WHISPER_MODEL WHISPER_RUNTIME_THREADS)) {
   299	        exists $config{$key} && length $config{$key}
   300	            or fatal("Whisper configuration is missing $key");
   301	    }
   302	    assert_safe_absolute_path('WHISPER_CLI', $config{WHISPER_CLI});
   303	    assert_safe_absolute_path('WHISPER_MODEL', $config{WHISPER_MODEL});
   304	    -x $config{WHISPER_CLI} && -f $config{WHISPER_CLI}
   305	        or fatal("Whisper CLI is unavailable: $config{WHISPER_CLI}");
   306	    -r $config{WHISPER_MODEL} && -f $config{WHISPER_MODEL}
   307	        or fatal("Whisper model is unavailable: $config{WHISPER_MODEL}");
   308	    $config{WHISPER_RUNTIME_THREADS} =~ /\A(?:auto|[1-9][0-9]*)\z/
   309	        or fatal('WHISPER_RUNTIME_THREADS must be auto or a positive integer');
   310	    return \%config;
