   137	sub selection_plan {
   138	    my ($state_lines, @outputs) = @_;
   139	    my (@internal_outputs, @external_outputs, @hdmi_outputs);
   140	
   141	    for my $output_name (@outputs) {
   142	        if (is_internal_output($output_name)) {
   143	            push @internal_outputs, $output_name;
   144	        } else {
   145	            push @external_outputs, $output_name;
   146	            push @hdmi_outputs, $output_name if is_hdmi_output($output_name);
   147	        }
   148	    }
