   365	sub load_idle_topology {
   366	    my $path = idle_topology_state_path();
   367	    return () if !defined $path || !-r $path || -s $path > 65_536;
   368	
   369	    open my $fh, '<', $path or return ();
   370	    my $header = <$fh> // q{};
   371	    chomp $header;
   372	    if ($header ne 'v1') {
   373	        close $fh;
   374	        return ();
   375	    }
   376	
   377	    my @outputs;
   378	    my %seen;
   379	    while (my $line = <$fh>) {
   380	        chomp $line;
   381	        my @fields = split /\t/, $line, -1;
   382	        if (@fields != 7) {
   383	            close $fh;
   384	            return ();
   385	        }
   386	
   387	        my ($name, $enabled, $mode, $scale, $position, $transform, $logical_size) = @fields;
   388	        if (!output_name_safe($name) || $seen{$name}++ || $enabled !~ /\A(?:yes|no)\z/) {
   389	            close $fh;
   390	            return ();
   391	        }
   392	
   393	        my $output = {
   394	            enabled      => $enabled,
   395	            logical_size => $logical_size,
   396	            mode         => $mode,
   397	            name         => $name,
   398	            position     => $position,
   399	            scale        => $scale,
   400	            transform    => $transform,
   401	        };
   402	        if (!output_geometry_complete($output)) {
   403	            close $fh;
   404	            return ();
   405	        }
   406	        push @outputs, $output;
   407	    }
   408	    close $fh;
   409	    return @outputs;
   410	}
